-- Disposable/rolled-back fixtures. Never use genuine employees or wallets.
begin;
insert into public.tenants(tenant_id,business_name) values('e1111111-1111-4111-8111-111111111111','Employee SQL fixture A'),('f1111111-1111-4111-8111-111111111111','Employee SQL fixture B');
insert into auth.users(id,email,is_anonymous) values('e2222222-2222-4222-8222-222222222222','payroll-sql-a@example.invalid',false),('f2222222-2222-4222-8222-222222222222','payroll-sql-b@example.invalid',false);
insert into public.user_profiles(user_id,tenant_id,email) values('e2222222-2222-4222-8222-222222222222','e1111111-1111-4111-8111-111111111111','payroll-sql-a@example.invalid'),('f2222222-2222-4222-8222-222222222222','f1111111-1111-4111-8111-111111111111','payroll-sql-b@example.invalid');
insert into public.roles(tenant_id,role_id,name) values('e1111111-1111-4111-8111-111111111111','e4444444-4444-4444-8444-444444444444','OWNER'),('f1111111-1111-4111-8111-111111111111','f4444444-4444-4444-8444-444444444444','OWNER');
insert into public.role_permissions select r.tenant_id,r.role_id,p.permission_id from public.roles r cross join public.permissions p where r.tenant_id in ('e1111111-1111-4111-8111-111111111111','f1111111-1111-4111-8111-111111111111');
insert into public.user_roles values('e1111111-1111-4111-8111-111111111111','e2222222-2222-4222-8222-222222222222','e4444444-4444-4444-8444-444444444444'),('f1111111-1111-4111-8111-111111111111','f2222222-2222-4222-8222-222222222222','f4444444-4444-4444-8444-444444444444');
create function pg_temp.employee_assert(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',msg; end if; end $$;
create function pg_temp.employee_reject(q text,expected text) returns void language plpgsql as $$ begin
 begin execute q; exception when others then if position(lower(expected) in lower(sqlerrm))=0 then raise exception 'Expected %; got %',expected,sqlerrm; end if; return; end;
 raise exception 'Expected rejection: %',expected; end $$;
grant execute on function pg_temp.employee_assert(boolean,text),pg_temp.employee_reject(text,text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','e2222222-2222-4222-8222-222222222222',true);
do $$ declare e uuid; scheduled uuid; p uuid; b uuid; cash uuid; bank uuid; tr uuid; truck uuid; result jsonb; balance jsonb; body jsonb; profile jsonb; request uuid:=gen_random_uuid();
 today date:=(now() at time zone 'Asia/Dhaka')::date; month date:=date_trunc('month',now() at time zone 'Asia/Dhaka')::date; future date:=(date_trunc('month',now() at time zone 'Asia/Dhaka')+interval '2 months')::date;
begin
 select wallet_id into cash from public.get_payment_wallets() where type='cash'; select wallet_id into bank from public.get_payment_wallets() where type='dealership';
 body:='{"name":"Employee SQL Driver","phones":[{"phone":"01700000031","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Driver","terms":{"monthly_salary":20000,"effective_from":"2025-02-10","is_active":true}}';
 e:=(public.save_employee(body,request)->>'employee_id')::uuid;
 perform pg_temp.employee_assert(public.save_employee(body,request)->>'employee_id'=e::text,'profile request exact once');
 perform pg_temp.employee_reject(format('select public.save_employee(%L,%L)',body||'{"name":"changed"}',request),'different details');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,'2025-02-01')->>'salary_amount')::numeric=20000,'joining month full rate');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,'2025-01-01')->>'salary_amount')::numeric=0,'before joining no salary');
 scheduled:=(public.save_employee('{"name":"Scheduled employee","phones":[{"phone":"01700000032","is_primary":true}],"business_unit":"gas_business","terms":{"monthly_salary":10000,"effective_from":"2035-02-10","is_active":true}}',gen_random_uuid())->>'employee_id')::uuid;
 profile:=public.get_employee_profile(scheduled)->'employee';
 perform pg_temp.employee_assert((profile->>'current_salary')::numeric=10000 and not (profile->>'is_active')::boolean,'scheduled employee retains configured salary');
 perform pg_temp.employee_assert((public.get_employee_salary_month(scheduled,'2035-01-01')->>'salary_amount')::numeric=0 and (public.get_employee_salary_month(scheduled,'2035-02-01')->>'salary_amount')::numeric=10000,'future joining month eligibility');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'outstanding')::numeric=20000,'future automatically available');
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','salary','period',future,'payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',3000),jsonb_build_object('wallet_id',bank,'amount',2000,'reference','EMPLOYEE-SPLIT')))));
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',body,gen_random_uuid()),'one wallet');
 body:=jsonb_set(body,'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',5000)));
 request:=gen_random_uuid(); result:=public.employee_payment_operation(body,request); p:=(result->'payment_ids'->>0)::uuid;
 perform pg_temp.employee_assert(public.employee_payment_operation(body,request)=result,'payment request exact once');
 balance:=public.get_employee_salary_month(e,future);
 perform pg_temp.employee_assert((balance->>'salary_amount')::numeric=20000 and (balance->>'paid')::numeric=5000 and (balance->>'outstanding')::numeric=15000,'5000 paid directly toward future 20000 salary');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,payments,0,amount}','15001'),gen_random_uuid()),'exceeds outstanding');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,payments,0,amount}','1.001'),gen_random_uuid()),'decimal places');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,kind}','"advance"'),gen_random_uuid()),'category');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_build_object('action','prepare','period',month),gen_random_uuid()),'Unknown');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items}',(body->'items')||(body->'items')),gen_random_uuid()),'one employee');
 body:=jsonb_set(body,'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',1000)));
 perform public.employee_payment_operation(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'paid')::numeric=6000,'repeated partial payment');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,payment_date}',to_jsonb('-infinity'::text)),gen_random_uuid()),'employee_payment_date_finite');
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','bonus','bonus_name','Eid Bonus','payment_date',today,'description','Great work','payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',700)))));
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,payments}',(body#>'{items,0,payments}')||(body#>'{items,0,payments}')),gen_random_uuid()),'one wallet');
 b:=(public.employee_payment_operation(body,gen_random_uuid())->'payment_ids'->>0)::uuid;
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'outstanding')::numeric=14000,'bonus does not affect salary');
 perform pg_temp.employee_assert((public.get_employee_activity(jsonb_build_object('employee_id',e,'search','Eid Bonus'))->>'total')::int=1,'named bonus searchable');
 perform public.employee_payment_operation(jsonb_build_object('action','reverse_payment','payment_id',b,'payment_date',today,'reason','Funds actually returned'),gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','reverse_payment','payment_id',p,'payment_date',today,'reason','Correct allocation'),gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'paid')::numeric=1000,'return reopens correct month');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_build_object('action','reverse_payment','payment_id',p,'payment_date',today,'reason','Duplicate'),gen_random_uuid()),'already been reversed');
 profile:=public.get_employee_profile(e)->'employee';
 body:=profile||jsonb_build_object('terms',jsonb_build_object('effective_from',month,'monthly_salary',22000,'is_active',true,'reason','Salary revision'));
 perform public.save_employee(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'salary_amount')::numeric=20000,'established future month keeps original amount');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,(future+interval '1 month')::date)->>'salary_amount')::numeric=22000,'unpaid unestablished future month uses revised salary');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,'2025-02-01')->>'salary_amount')::numeric=20000,'historical salary unchanged');
 perform pg_temp.employee_reject(format('select public.save_employee(%L,%L)',body,gen_random_uuid()),'Employee changed');
 body:=(public.get_employee_profile(e)->'employee')||jsonb_build_object('terms',jsonb_build_object('effective_from',today,'monthly_salary',22000,'is_active',false,'reason','Left employment'));
 perform public.save_employee(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_profile(e)->'employee'->>'is_active')::boolean=false,'status changes today');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,(future+interval '1 month')::date)->>'salary_amount')::numeric=0,'inactive full month has no new salary');
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,future)->>'salary_amount')::numeric=20000,'leaving preserves established month');
 body:=(public.get_employee_profile(e)->'employee')||jsonb_build_object('terms',jsonb_build_object('effective_from',today,'monthly_salary',22000,'is_active',true,'reason','Same-day correction'));
 perform public.save_employee(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_profile(e)->'employee'->>'is_active')::boolean,'same-day reactivation appends revision');
 body:=(public.get_employee_profile(e)->'employee')||jsonb_build_object('terms',jsonb_build_object('effective_from',case when extract(day from today)=1 then today else (month+interval '1 month')::date end,'monthly_salary',23000,'is_active',true,'reason','Same-day salary correction'));
 perform public.save_employee(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_profile(e)->'terms'->0->>'monthly_salary')::numeric=23000,'salary revision follows a monthly boundary');
 -- Past month full settlement needs no preparation.
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','salary','period','2025-02-01','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',20000)))));
 perform public.employee_payment_operation(body,gen_random_uuid());
 perform pg_temp.employee_assert((public.get_employee_salary_month(e,'2025-02-01')->>'outstanding')::numeric=0,'past full payment');
 -- Trips remain part of saved Logistics cost, charged once.
 truck:=(public.save_vehicle(jsonb_build_object('name','Employee SQL vehicle','serial_no','EMPLOYEE-SQL','capacity',10,'driver_employee_id',e,'book_value',0,'funding','opening'),gen_random_uuid())->>'vehicle_id')::uuid;
 tr:=(public.create_custom_transit(jsonb_build_object('vehicle_id',truck,'fee',0,'client_name','Employee SQL trip','destination','Dhaka'),gen_random_uuid())->>'transit_id')::uuid;
 perform public.save_transit_costs(tr,'{"driver_cost":500,"helper_cost":0,"oil_cost":50,"others_cost":0}',1);
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',today,'description','Driver trip','payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',300)))));
 perform public.employee_payment_operation(body,gen_random_uuid());
 perform pg_temp.employee_reject(format('select public.save_transit_costs(%L,%L,3)',tr,'{"driver_cost":200,"helper_cost":0,"oil_cost":50,"others_cost":0}'),'below employee payments');
 perform pg_temp.employee_reject(format('select public.transition_transit(%L,%L,3)',tr,'complete'),'outstanding');
 body:=jsonb_set(body,'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',200))); perform public.employee_payment_operation(body,gen_random_uuid());
 perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',50))),gen_random_uuid());
 perform public.transition_transit(tr,'complete',5);
 perform pg_temp.employee_assert((public.get_transit_payroll(tr)->>'driver_paid')::numeric=500,'Logistics allocation retained');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',body,gen_random_uuid()),'open operating costs');
 perform set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
 perform pg_temp.employee_reject(format('select public.get_employee_profile(%L)',e),'not found');
 perform pg_temp.employee_reject(format('select public.get_employee_salary_month(%L,%L)',e,future),'not found');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',body,gen_random_uuid()),'open operating costs');
end $$;
reset role;
select pg_temp.employee_assert(not exists(select 1 from public.wallets w where tenant_id='e1111111-1111-4111-8111-111111111111' and balance<>opening_balance+coalesce((select sum(amount) from public.wallet_transactions x where x.tenant_id=w.tenant_id and x.wallet_id=w.wallet_id),0)),'wallet reconciliation');
select pg_temp.employee_assert(not exists(select 1 from public.employee_payment_entries e join public.employee_payments p using(tenant_id,payment_id) left join public.wallet_transactions w on w.tenant_id=e.tenant_id and w.employee_entry_id=e.entry_id where e.tenant_id='e1111111-1111-4111-8111-111111111111' and (w.transaction_id is null or abs(w.amount)<>e.amount or (w.amount>0)<>(p.reversal_of is not null))),'one correctly signed posting per payment entry');
select pg_temp.employee_assert(to_regclass('public.payroll_adjustments') is null and to_regprocedure('public.payroll_operation(jsonb,uuid)') is null,'obsolete implementation removed');
select 'PASS: employee creation/revisions/status, automatic past/current/future salaries, single-wallet/repeated payments, named bonuses, returns, idempotency, wallet reconciliation, Logistics and tenant isolation';
rollback;

